import { useState } from "react";
import "./Title.css";

function Title({ data }) {
  const [sort, setSort] = useState(data);

  function sortName() {
    let name = false;
    if (!name) {
      let sortedNameAZ = sort.toSorted((a, b) => a.name.localeCompare(b.name));
      setSort(sortedNameAZ);
      name = true;
    } else if (name) {
      let sortedNameZA = sort.toSorted((a, b) => b.name.localeCompare(a.name));
      setSort(sortedNameZA);
      name = false;
    }
    console.log(sortedNameAZ);
  }

  // function sortByText(text) {}

  return (
    <div className="mainTitle">
      <p className="titleP">Image</p>
      <div className="name" onClick={sortName}>
        <p className="titleP">Name</p>
        <svg
          xmlns="http://www.w3.org/2000/svg"
          height="24px"
          viewBox="0 -960 960 960"
          width="24px"
          fill="#e8eaed"
        >
          <path d="M440-800v487L216-537l-56 57 320 320 320-320-56-57-224 224v-487h-80Z" />
        </svg>
      </div>
      <p className="titleP">Surname</p>
      <p className="titleP">Age</p>
      <p className="titleP">Gender</p>
      <p className="titleP">Profession</p>
    </div>
  );
}

export default Title;
